-- Face-Name Match schema and seed library.
-- Generated personas: 60. Generated sets: 600.
-- Maximum shared avatar traits inside any playable set: 4.
-- Maximum shared avatar traits across the full persona library: 9.

CREATE EXTENSION IF NOT EXISTS pgcrypto;

CREATE TABLE IF NOT EXISTS public.face_name_personas (
  id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  name_es         TEXT NOT NULL,
  name_de         TEXT NOT NULL,
  name_en         TEXT NOT NULL,
  avatar_config   JSONB NOT NULL,
  age_group       TEXT NOT NULL CHECK (age_group IN ('young_adult', 'middle_aged', 'senior')),
  gender_presenta TEXT NOT NULL CHECK (gender_presenta IN ('feminine', 'masculine', 'neutral')),
  is_active       BOOLEAN NOT NULL DEFAULT TRUE,
  created_at      TIMESTAMPTZ DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS public.face_name_sets (
  id               UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  persona_ids      JSONB NOT NULL,
  face_count       INTEGER NOT NULL,
  difficulty_tier  INTEGER NOT NULL CHECK (difficulty_tier BETWEEN 1 AND 10),
  recall_modes     JSONB NOT NULL,
  study_seconds    INTEGER NOT NULL,
  language         TEXT NOT NULL DEFAULT 'es',
  is_active        BOOLEAN NOT NULL DEFAULT TRUE,
  created_at       TIMESTAMPTZ DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS public.face_name_sessions (
  id                    UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id               UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  played_at             TIMESTAMPTZ DEFAULT NOW(),
  set_id                UUID REFERENCES public.face_name_sets(id),
  difficulty_tier       INTEGER NOT NULL,
  face_count            INTEGER NOT NULL,
  n2f_attempts          INTEGER NOT NULL DEFAULT 0,
  n2f_correct           INTEGER NOT NULL DEFAULT 0,
  n2f_accuracy_pct      NUMERIC(5,2),
  f2n_attempts          INTEGER NOT NULL DEFAULT 0,
  f2n_correct           INTEGER NOT NULL DEFAULT 0,
  f2n_accuracy_pct      NUMERIC(5,2),
  overall_accuracy_pct  NUMERIC(5,2),
  score                 INTEGER,
  completed             BOOLEAN NOT NULL DEFAULT FALSE,
  abandoned             BOOLEAN NOT NULL DEFAULT FALSE,
  duration_seconds      INTEGER
);

CREATE TABLE IF NOT EXISTS public.face_name_user_state (
  user_id               UUID PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE,
  current_tier          INTEGER NOT NULL DEFAULT 1 CHECK (current_tier BETWEEN 1 AND 10),
  sessions_at_tier      INTEGER NOT NULL DEFAULT 0,
  consecutive_wins      INTEGER NOT NULL DEFAULT 0,
  consecutive_losses    INTEGER NOT NULL DEFAULT 0,
  total_sessions        INTEGER NOT NULL DEFAULT 0,
  best_score            INTEGER NOT NULL DEFAULT 0,
  last_played_at        TIMESTAMPTZ,
  streak_days           INTEGER NOT NULL DEFAULT 0,
  last_streak_date      DATE,
  updated_at            TIMESTAMPTZ DEFAULT NOW()
);

ALTER TABLE public.face_name_sessions ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.face_name_user_state ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.face_name_sets ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.face_name_personas ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS user_own_fn_sessions ON public.face_name_sessions;
CREATE POLICY user_own_fn_sessions ON public.face_name_sessions
  FOR ALL USING (auth.uid() = user_id)
  WITH CHECK (auth.uid() = user_id);

DROP POLICY IF EXISTS user_own_fn_state ON public.face_name_user_state;
CREATE POLICY user_own_fn_state ON public.face_name_user_state
  FOR ALL USING (auth.uid() = user_id)
  WITH CHECK (auth.uid() = user_id);

DROP POLICY IF EXISTS fn_sets_read ON public.face_name_sets;
CREATE POLICY fn_sets_read ON public.face_name_sets
  FOR SELECT USING (auth.role() = 'authenticated');

DROP POLICY IF EXISTS fn_personas_read ON public.face_name_personas;
CREATE POLICY fn_personas_read ON public.face_name_personas
  FOR SELECT USING (auth.role() = 'authenticated');

CREATE INDEX IF NOT EXISTS idx_fns_user_played ON public.face_name_sessions (user_id, played_at DESC);
CREATE INDEX IF NOT EXISTS idx_fnsets_tier ON public.face_name_sets (difficulty_tier, is_active, language);

ON CONFLICT (id) DO UPDATE SET
  name_es = EXCLUDED.name_es,
  name_de = EXCLUDED.name_de,
  name_en = EXCLUDED.name_en,
  avatar_config = EXCLUDED.avatar_config,
  age_group = EXCLUDED.age_group,
  gender_presenta = EXCLUDED.gender_presenta,
  is_active = TRUE;

ON CONFLICT (id) DO UPDATE SET
  persona_ids = EXCLUDED.persona_ids,
  face_count = EXCLUDED.face_count,
  difficulty_tier = EXCLUDED.difficulty_tier,
  recall_modes = EXCLUDED.recall_modes,
  study_seconds = EXCLUDED.study_seconds,
  language = EXCLUDED.language,
  is_active = TRUE;
